open Ogpu.Transfer_ring
let fail s=raise(Failure s)
let ok=function Ok x->x|Error e->fail(Ogpu.Error.to_string e)
let expect k=function Error(e:Ogpu.Error.t)when e.kind=k->()|_->fail"expected error"
let ()=let d=Ogpu.Handle.create_device()in let r=ok(create~device:d~capacity:64L~alignment:16L~max_slots:2)in let src=Bytes.of_string"abcdefghijklmnop"in let a=ok(reserve r~direction:Upload~policy:Copy~bytes:src~length:16L())and b=ok(reserve r~direction:Readback~policy:Borrow~length:16L())in if List.map(fun x->x.index)(reservations r)<>[1L;2L]then fail"order";expect Ogpu.Error.Capacity(reserve r~direction:Upload~policy:Copy~length:1L());ignore(ok(commit a~epoch:2L));expect Ogpu.Error.Invalid_state(commit a~epoch:3L);ignore(ok(cancel b));expect Ogpu.Error.Stale_handle(snapshot b);expect Ogpu.Error.Capacity(reserve r~direction:Upload~policy:Copy~length:64L());ignore(ok(reclaim r~completed_epoch:1L));if live_slots r<>1 then fail"early reclaim";ignore(ok(reclaim r~completed_epoch:2L));if live_slots r<>0 then fail"reclaim";Bytes.set src 0 'z';(match ok(payload a)with Some p when Bytes.get p 0='a'->()|_->fail"copy policy");let stress=ok(create~device:d~capacity:16L~alignment:16L~max_slots:1)in for e=1 to 100000 do let x=ok(reserve stress~direction:Upload~policy:Copy~length:16L())in ignore(ok(commit x~epoch:(Int64.of_int e)));ignore(ok(reclaim stress~completed_epoch:(Int64.of_int e)));if live_slots stress<>0 then fail"slot growth"done;let prepare n=List.init 50(fun i->n+i)in let expected=List.concat_map prepare[0;50;100;150]|>List.sort compare in let ws=Array.init 4(fun i->Domain.spawn(fun()->prepare(i*50)))in let got=Array.to_list ws|>List.concat_map Domain.join|>List.sort compare in if got<>expected then fail"domain order";destroy r;expect Ogpu.Error.Stale_handle(reserve r~direction:Upload~policy:Copy~length:1L());print_endline"OGPU bounded transfer ring passed"
